	@Test
	void semanticQueriesMatchIndependentMemoryStore() {
		SailRepository memory = new SailRepository(new MemoryStore());
		try (var connection = repository.getConnection(); var oracle = memory.getConnection()) {
			// These five logical inputs come from the frozen producer contract, independently of LMDB reads.
			oracle.add(expectedStatements());
			String prefix = "PREFIX l: <urn:legacy:> ";
			for (String query : List.of(
					"SELECT DISTINCT ?v WHERE {?s l:label ?v FILTER(isLiteral(?v))}",
					"SELECT ?v (COUNT(?s) AS ?n) WHERE {?s l:label ?v FILTER(isLiteral(?v))} GROUP BY ?v",
					"SELECT ?a ?b WHERE {?a l:label ?v . ?b l:label ?v FILTER(isLiteral(?v))}",
					"SELECT ?a ?b WHERE {?a l:label ?x . ?b l:label ?y FILTER(isLiteral(?x) && sameTerm(?x,?y))}",
					"SELECT ?s ?b WHERE {?s l:label \"language value\"@EN OPTIONAL {?b l:label \"language value\"@en}}",
					"SELECT ?s WHERE {{?s l:label \"language value\"@EN} UNION {?s l:label \"language value\"@en}}",
					"SELECT ?s WHERE {?s l:label \"language value\"@EN MINUS {?s l:label \"language value\"@en}}",
					"SELECT ?s WHERE {?s l:label ?v FILTER(isLiteral(?v) && EXISTS {?s l:label \"language value\"@EN})}",
					"SELECT ?s WHERE {?s l:label ?v FILTER(isLiteral(?v) && NOT EXISTS {?s l:label \"language value\"@EN})}")) {
				assertThat(QueryResults.asList(connection.prepareTupleQuery(prefix + query).evaluate()))
						.as(query)
						.containsExactlyInAnyOrderElementsOf(
								QueryResults.asList(oracle.prepareTupleQuery(prefix + query).evaluate()));
			}
		} finally {
			memory.shutDown();
		}
	}

