	@ParameterizedTest
	@ValueSource(ints = { 0, 2 })
	void heldSnapshotSurvivesAliasRetirementRollbackAndReopen(int bulkSize) {
		repository.shutDown();
		open(bulkSize);
		try (var snapshot = repository.getConnection(); var writer = repository.getConnection()) {
			snapshot.begin(IsolationLevels.SNAPSHOT);
			List<Statement> held = QueryResults.asList(snapshot.getStatements(null, null, null, false));
			assertThat(held).containsExactlyInAnyOrderElementsOf(expectedStatements());
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.clear();
			writer.commit();
			assertThat(writer.size()).isZero();
			assertThat(snapshot.size()).isEqualTo(5);
			assertThat(snapshot.hasStatement(null, LABEL, VALUES.createLiteral("language value", "eN"), false))
					.isTrue();
			writer.begin(IsolationLevels.SNAPSHOT);
			for (int index = 0; index < 128; index++) {
				writer.add(VALUES.createIRI("urn:legacy:replacement:" + index), LABEL,
						VALUES.createLiteral("replacement " + index), CONTEXT);
			}
			writer.commit();
			assertThat(QueryResults.asList(snapshot.getStatements(null, null, null, false)))
					.containsExactlyInAnyOrderElementsOf(expectedStatements());
			assertThat(held).containsExactlyInAnyOrderElementsOf(expectedStatements());
			snapshot.rollback();
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.clear();
			writer.add(VALUES.createIRI("urn:legacy:after-clear"), LABEL,
					VALUES.createLiteral("after clear", "eN"), CONTEXT);
			writer.rollback();
			assertThat(writer.size()).isEqualTo(128);
			writer.begin(IsolationLevels.SNAPSHOT);
			writer.clear();
			writer.add(VALUES.createIRI("urn:legacy:after-clear"), LABEL,
					VALUES.createLiteral("after clear", "eN"), CONTEXT);
			writer.commit();
			assertThat(writer.size()).isEqualTo(1);
		}
		repository.shutDown();
		open(bulkSize);
		try (var connection = repository.getConnection()) {
			assertThat(connection.size()).isEqualTo(1);
			assertThat(connection.hasStatement(VALUES.createIRI("urn:legacy:after-clear"), LABEL,
					VALUES.createLiteral("after clear", "EN"), false, CONTEXT)).isTrue();
			assertThat(connection.hasStatement(null, LABEL, LOWER, false)).isFalse();
		}
	}

