	@Test
	void oneBulkBatchDeduplicatesDistinctPhysicalAliasIds() throws Exception {
		repository.shutDown();
		open(128);
		Value lower;
		Value upper;
		try (var connection = repository.getConnection()) {
			lower = QueryResults.asList(connection.getStatements(VALUES.createIRI("urn:legacy:lower"), LABEL,
					null, false)).getFirst().getObject();
			upper = QueryResults.asList(connection.getStatements(VALUES.createIRI("urn:legacy:upper"), LABEL,
					null, false)).getFirst().getObject();
		}
		assertThat(((LmdbValue) lower).getInternalID()).isNotEqualTo(((LmdbValue) upper).getInternalID());
		Set<Statement> statements = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int index = 0; index < 20; index++) {
			IRI owner = VALUES.createIRI("urn:legacy:batch-owner:" + index);
			statements.add(VALUES.createStatement(owner, LABEL, lower, CONTEXT));
			statements.add(VALUES.createStatement(owner, LABEL, upper, CONTEXT));
		}
		var backing = ((LmdbStore) repository.getSail()).getBackingStore();
		try (var sink = backing.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			sink.approveAll(statements, Set.of(CONTEXT));
			sink.flush();
		}
		repository.shutDown();
		assertThat(LmdbCompatibilityFixtures.nativeTripleEntryCount(directory, "spocspoc"))
				.as("each newly approved RDF quad has exactly one physical record")
				.isEqualTo(28);
		open(128);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nativeAlignedBatchTracksLanguageRowsForLaterAliasBatches(boolean inferred) throws Exception {
		repository.shutDown();
		open(128);
		Value lower;
		Value upper;
		try (var connection = repository.getConnection()) {
			lower = QueryResults.asList(connection.getStatements(VALUES.createIRI("urn:legacy:lower"), LABEL,
					null, false)).getFirst().getObject();
			upper = QueryResults.asList(connection.getStatements(VALUES.createIRI("urn:legacy:upper"), LABEL,
					null, false)).getFirst().getObject();
		}
		Set<Statement> first = Collections.newSetFromMap(new IdentityHashMap<>());
		Set<Statement> second = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int index = 0; index < 128; index++) {
			IRI owner = VALUES.createIRI("urn:legacy:aligned-owner:" + index);
			first.add(VALUES.createStatement(owner, LABEL, index % 2 == 0 ? lower : upper, CONTEXT));
			second.add(VALUES.createStatement(owner, LABEL, index % 2 == 0 ? upper : lower, CONTEXT));
		}
		var backing = ((LmdbStore) repository.getSail()).getBackingStore();
		var source = inferred ? backing.getInferredSailSource() : backing.getExplicitSailSource();
		try (var sink = source.sink(IsolationLevels.NONE)) {
			// Both input sets fill the existing aligned batch; the second uses the other authentic physical ID.
			sink.approveAll(first, Set.of(CONTEXT));
			sink.approveAll(second, Set.of(CONTEXT));
			sink.flush();
		}
		repository.shutDown();
		assertThat(LmdbCompatibilityFixtures.nativeTripleEntryCount(directory,
				inferred ? "spocspoc-inf" : "spocspoc"))
						.as("aligned inserts must update the same writer index used by the later alias batch")
						.isEqualTo(inferred ? 128 : 136);
		open(128);
		try (var connection = repository.getConnection()) {
			for (int index = 0; index < 128; index++) {
				assertThat(connection.hasStatement(VALUES.createIRI("urn:legacy:aligned-owner:" + index), LABEL,
						VALUES.createLiteral("language value", "eN"), true, CONTEXT)).isTrue();
			}
		}
	}

